events=[]
class Failure(TypeError): pass
class Name(str):
 def __str__(self): raise ValueError('coercion')
 def __hash__(self):
  events.append('hash')
  return str.__hash__(self)
 def __eq__(self, other):
  events.append(('eq', str.__str__(other)))
  return str.__eq__(self, other)

name=Name('field')
class Descriptor:
 def __get__(self, obj, cls):
  events.append('descriptor get')
  return 31
 def __set__(self, obj, value):
  events.append(('descriptor set', value))
 def __delete__(self, obj):
  events.append('descriptor delete')
class Meta(type):
 def __getattribute__(self, key):
  events.append(('meta get', key is name))
  return 19
 def __setattr__(self, key, value):
  events.append(('meta set', key is name, value))
 def __delattr__(self, key):
  events.append(('meta del', key is name))
class C:
 pass


target=C()

events=[]
try:
 value=getattr(target, name)
 result=('ok', value)
except Exception as error:
 result=(type(error).__name__, str(error))
result=(result, events)

